namespace RonSijm.FluidHumidifier.Factories.EventsV2;

public class InnerSubscriberInvokeConfigurationFactory(Action<Humidifier.EventsV2.SubscriberTypes.InvokeConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EventsV2.SubscriberTypes.InvokeConfiguration>
{

    internal InnerSubscriberStepFunctionsParametersFactory StepFunctionsParametersFactory { get; set; }

    internal InnerSubscriberSqsParametersFactory SqsParametersFactory { get; set; }

    internal InnerSubscriberSnsParametersFactory SnsParametersFactory { get; set; }

    internal InnerSubscriberHttpParametersFactory HttpParametersFactory { get; set; }

    internal InnerSubscriberEventBusV2ParametersFactory EventBusV2ParametersFactory { get; set; }

    internal InnerSubscriberUniversalTargetParametersFactory UniversalTargetParametersFactory { get; set; }

    internal InnerSubscriberKinesisParametersFactory KinesisParametersFactory { get; set; }

    internal InnerSubscriberLambdaParametersFactory LambdaParametersFactory { get; set; }

    protected override Humidifier.EventsV2.SubscriberTypes.InvokeConfiguration Create()
    {
        var invokeConfigurationResult = CreateInvokeConfiguration();
        factoryAction?.Invoke(invokeConfigurationResult);

        return invokeConfigurationResult;
    }

    private Humidifier.EventsV2.SubscriberTypes.InvokeConfiguration CreateInvokeConfiguration()
    {
        var invokeConfigurationResult = new Humidifier.EventsV2.SubscriberTypes.InvokeConfiguration();

        return invokeConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EventsV2.SubscriberTypes.InvokeConfiguration result)
    {
        base.CreateChildren(result);

        result.StepFunctionsParameters ??= StepFunctionsParametersFactory?.Build();
        result.SqsParameters ??= SqsParametersFactory?.Build();
        result.SnsParameters ??= SnsParametersFactory?.Build();
        result.HttpParameters ??= HttpParametersFactory?.Build();
        result.EventBusV2Parameters ??= EventBusV2ParametersFactory?.Build();
        result.UniversalTargetParameters ??= UniversalTargetParametersFactory?.Build();
        result.KinesisParameters ??= KinesisParametersFactory?.Build();
        result.LambdaParameters ??= LambdaParametersFactory?.Build();
    }

} // End Of Class

